    // Codes of the items that hold up the next step, in checklist order.
    blockers(): string[] {
        const side = this.openSide();
        if (side === undefined) return [];
        return this.lists[side].items
            .filter((item) => item.must && (item.state === "todo" || item.state === "fault"))
            .map((item) => item.code);
    }

